    slugEs: "majestic-hotel-barcelona-al-aeropuerto-de-barcelona",
    originNameEn: "Majestic Hotel & Spa Barcelona",
    originNameEs: "Majestic Hotel & Spa Barcelona",
    destinationNameEn: "Barcelona Airport",
    destinationNameEs: "Aeropuerto de Barcelona",
    areaEn: "Passeig de Gràcia",
