    direction: "from-city",
    originCitySlug: "barcelona",
    slugEn: "barcelona-to-andorra-day-trip",
    slugEs: "barcelona-a-andorra-excursion-de-un-dia",
    originNameEn: "Barcelona",
    originNameEs: "Barcelona",
